  texto = String((msg.image && msg.image.caption) || '').slice(0, 1500);
  textoReporte = '(imagen) el cliente envió una foto';
} else if (tipo === 'document') {
  texto = String((msg.document && msg.document.caption) || '').slice(0, 1500);
