    } else {
      const lista = filas.map((x) => ({ id: x.id, title: verbo + ' ' + x.c.etiqueta, description: x.c.titulo }));
      agregar('paciente', mLista(cuerpo, 'Ver mis citas', 'Tus citas', lista), cuerpo, cuerpo, { tipoReporte: 'interactive' });
    }
    break;
  }

  case 'sin_citas':
    transferir(params.motivo || 'no encontró sus citas',
      'No encuentro ninguna cita registrada con este número de WhatsApp. Si crees que es un error, escríbele directo a recepción tocando el botón.');
    break;

  case 'cancelar': {
    const b = cnPrimero('Borrar evento');
    if (!b || b.error) {
      errores.push('no se pudo borrar la cita del calendario');
      transferir('no se pudo cancelar la cita en el calendario', 'No pude cancelar tu cita. Escríbele directo a recepción tocando el botón.');
      break;
    }
    const c = base.cancelada || {};
    const cuerpo = conEmoji('✅') + 'Listo, cancelé tu cita del ' + textoDeFecha(c.inicio) + '.';
    agregar('paciente', mTexto(cuerpo), cuerpo, cuerpo, { tipoReporte: 'text' });
    break;
  }

  case 'crear': {
    if (!base.creada) { // no deberia pasar: `Candado` cambia el plan si no se creo
      transferir('no se pudo crear la cita', String(cfg.mensajeErrorTemporal || '') + ' Si prefieres, escríbele directo a recepción.');
      break;
    }
    const c = base.crear;
    const nombres = c.titulo.replace(/\s*\((?:CNS|RN)\)\s*$/, '');
    const partes = [
      conEmoji('✅') + 'Listo, quedó agendada la cita de ' + nombres + ' (' + (CN_NOMBRE_SERVICIO[c.servicio] || 'consulta') + '): ' + textoDeFecha(c.inicio) + '.',
      cfg.direccion ? 'Te esperamos en ' + cfg.direccion + '.' + (MAPA ? '\nMapa: ' + MAPA : '') : '',
      // P10: la tolerancia va dentro del mismo mensaje y sale de la configuracion; sin frase, no se agrega.
      String(cfg.toleranciaTexto || ''),
      String(cfg.mensajeCierre || ''),
    ].filter(Boolean);
    let cuerpo = partes.join('\n\n');
    const b = cnPrimero('Borrar evento');
    if (base.borrarId && (!b || b.error)) {
      // Reagendo, la nueva quedo, pero la anterior no se pudo borrar: se dice y pasa a recepcion.
      errores.push('no se pudo borrar la cita anterior al reagendar');
      cuerpo += '\n\nNo pude cancelar tu cita anterior: escríbele directo a recepción para que la anulen.';
      mensajeConBoton(rec, cnRecorte(cuerpo, 1024), 'Escribir a recepción', 'Hola, escribo desde el asistente de ' + nombreNegocio + '.', 'no_contactar');
      avisarARecepcion('reagendó y no se pudo borrar la cita anterior: quedan dos citas de este paciente');
    } else {
      agregar('paciente', mTexto(cuerpo), cuerpo, cuerpo, { tipoReporte: 'text' });
      // Petición del doctor (fila 23 de la aceptación): las redes van en un SEGUNDO mensaje, como en el flujo
      // actual. +1 mensaje por cita confirmada (0,0113 USD), declarado en DISENO.md.
      const redes = String(cfg.mensajeRedes || '').trim();
      if (redes) agregar('paciente', mTexto(redes), redes, redes, { tipoReporte: 'text' });
    }
    break;
  }

  case 'transferir':
    transferir(params.motivo || 'consulta sin respuesta', params.rechazos
      // HB4: tres rechazos seguidos de ofertas.
      ? 'Disculpa que ninguno de los horarios te sirva. Para buscar otra opción, escríbele directo a recepción tocando el botón.'
      : 'Esa consulta no la puedo resolver por este chat. Escríbele directo a recepción tocando el botón.');
    break;

  case 'error':
  default: {
    const motivo = params.motivo || errores.join('; ') || 'error del flujo';
    const cuerpo = String(cfg.mensajeErrorTemporal || '').trim() + ' Si prefieres, escríbele directo a recepción.';
    transferir(motivo, cuerpo);
  }
}

// La cita cruzada no se pudo deshacer: dos eventos quedaron en el calendario.
if (base.deshacerId) {
  const d = cnPrimero('Deshacer cita');
  // Un 404 o 410 de Google es que el evento ya no está: el deshacer cumplió.
  const yaNoEsta = !!(d && d.error) && /\b(404|410)\b|not found|has been deleted|resource has been deleted/i.test(JSON.stringify(d.error));
  if ((!d || d.error) && !yaNoEsta) {
    deshacerFallo = true;
    errores.push('no se pudo deshacer la cita cruzada');
    const motivo = 'la cita cruzada no se pudo borrar del calendario (evento ' + base.deshacerId + '): revisar la agenda de ese horario';
    if (rec && rec !== desdeDigitos) avisarARecepcion(motivo);
    else if (doc && doc !== desdeDigitos) {
      const aviso = '🔔 NovuChat (' + nombreNegocio + '): ' + motivo + '.';
      agregar('doctor', mTexto(aviso), aviso, aviso, { tipoReporte: null });
    }
  }
}

// ====================================================== destinatarios, modo prueba, ids
const prueba = cfg.modoPrueba === true;
const telPrueba = String(cfg.telefonoDePrueba || '');
const PREFIJO = { recepcion: '[a recepción] ', doctor: '[al doctor] ' };
const salida = [];
for (const m of msgs) {
  let numero = m.para === 'paciente' ? String(t.from || '') : (m.para === 'recepcion' ? rec : doc);
  if (prueba) numero = telPrueba;
  if (!numero && !prueba) continue;
  const pre = prueba ? (PREFIJO[m.para] || '') : '';
  const p = m.payload;
  p.to = numero;
  let texto = pre + m.texto;
  let respaldo = pre + m.respaldo;
  if (pre) {
    if (p.type === 'text') p.text.body = pre + p.text.body;
    else if (p.type === 'interactive') p.interactive.body.text = cnRecorte(pre + p.interactive.body.text, 1024);
    else if (p.type === 'template') p.template.components[0].parameters[0].text = cnRecorte(pre + p.template.components[0].parameters[0].text, 200);
  }
  salida.push({ json: {
    para: numero, destino: m.para, payload: p, texto: texto, respaldo: respaldo,
    tipoReporte: m.tipoReporte || null, evento: m.evento,
    reportar: !prueba && m.para === 'paciente' && !!m.tipoReporte,
    phoneNumberId: cfg.phoneNumberId, waGraphVersion: cfg.waGraphVersion || 'v26.0',
    from: t.from, sinMensajes: false,
  } });
}

// ============================================ EL ESTADO: un solo lugar, al final del turno
const estado = base.estado && typeof base.estado === 'object' ? base.estado : null;
let estadoDespues = null;
if (estado && cnClaveValida(t.from) && plan !== 'nada') {
  const e = Object.assign(cnEstadoBase(), estado, { ultimoMensajeMs: ahora });
  e.pacientes = (e.pacientes || []).slice(0, 2).map((n) => String(n).slice(0, 80));
  e.ultimaOferta = (e.ultimaOferta || []).slice(0, 10);
  e.primerTexto = String(e.primerTexto || '').slice(0, 300);
  e.moverTitulo = String(e.moverTitulo || '').slice(0, 120);
  estadoDespues = e;
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (err) { sd = null; }
  if (sd) {
    if (!sd.agendaMinima || typeof sd.agendaMinima !== 'object') sd.agendaMinima = {};
    for (const k of Object.keys(sd.agendaMinima)) {
      const v = sd.agendaMinima[k];
      if (!v || !(ahora - Number(v.ultimoMensajeMs || 0) < CN_VENCE_MS)) delete sd.agendaMinima[k];
    }
    sd.agendaMinima[String(t.from)] = e;
  }
}

if (!salida.length) {
  return [{ json: { sinMensajes: true, para: '', payload: null, texto: '', respaldo: '', reportar: false, from: t.from,
    plan: plan, estadoDespues: estadoDespues, errores: errores, huecosOfrecidos: [], eventoCreadoId: '', eventoBorradoId: '' } }];
}
const oferta = base.oferta && Array.isArray(base.oferta.huecos) ? base.oferta.huecos : [];
const borradoOk = (() => { const b = cnPrimero('Borrar evento'); return !!base.borrarId && !!b && !b.error; })();
const resumen = {
  plan: plan, estadoDespues: estadoDespues, errores: errores,
  huecosOfrecidos: (plan === 'ofrecer' || plan === 'cruce' || plan === 'pedir_boton') ? oferta.map((h) => h.inicio) : [],
  eventoCreadoId: base.creada ? String(base.eventoCreadoId || '') : '',
  eventoBorradoId: borradoOk ? String(base.borrarId) : (base.deshacerId && !deshacerFallo ? String(base.deshacerId) : ''),
};
salida[0].json.resumen = resumen;
return salida;

// =============================================================================
// UTILIDADES COMUNES DE LOS NODOS DE «AGENDA MINIMA v0» (prefijo `cn` / `CN_`)
// =============================================================================
// El constructor las pega entre la libreria de agenda y el codigo de cada nodo
// (salvo en los nodos marcados «@@solo:»). Son JavaScript plano: sin `require`,
// sin `URL`, `Buffer` ni `crypto`, y nada de red. Lo que lee de otros nodos lo
// lee POR NOMBRE y solo si corrieron (`isExecuted`): un nodo que no corrio no
// se lee con `$('X').item`, y un nodo de envio o de reporte desactivado deja
// pasar su entrada, asi que nada de aca depende de lo que ellos devuelvan.

const CN_VENCE_MS = 30 * 60 * 1000;
const CN_SERVICIOS = ['control_recien_nacido', 'control_nino_sano'];
const CN_NOMBRE_SERVICIO = {
  control_recien_nacido: 'control del recién nacido',
  control_nino_sano: 'control del niño sano',
};

// El nodo `nombre` si existe Y corrio en esta ejecucion; si no, null. En un JSON
// que no lo trae (el de produccion no tiene «Entrada de prueba») `$()` lanza.
function cnNodo(nombre) {
  try {
    const n = $(nombre);
    return n && n.isExecuted ? n : null;
  } catch (e) {
    return null;
  }
}
function cnPrimero(nombre) {
  const n = cnNodo(nombre);
  if (!n) return null;
  try {
    const i = n.first();
    return i && i.json ? i.json : null;
  } catch (e) {
    return null;
  }
}
function cnTodos(nombre) {
  const n = cnNodo(nombre);
  if (!n) return [];
  try {
    return n.all().map((i) => (i && i.json) || {});
  } catch (e) {
    return [];
  }
}
function cnCfg() {
  return cnPrimero('Config del negocio') || {};
}

function cnNorm(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}
function cnDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}
function cnRecorte(t, max) {
  const s = String(t === undefined || t === null ? '' : t);
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}
// Una lista «a|b|c» de la configuracion a una regex que no cae en un patron de usuario.
function cnRegexDeLista(lista) {
  const partes = String(lista || '').split('|').map((p) => cnNorm(p)).filter(Boolean)
    .map((p) => p.replace(/[.*+?^${}()[\]\\]/g, '\\$&'));
  return partes.length ? new RegExp('(?<![\\p{L}\\p{N}])(?:' + partes.join('|') + ')', 'iu') : null;
}

// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con
// `simplify`). '' si vino un error o algo que no se reconoce.
function cnTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'transcription', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}
// El objeto JSON que Gemini devolvio como texto; null si no es un objeto.
function cnJsonDeGemini(j) {
  const t = cnTextoDeGemini(j).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!t) return null;
  try {
    const o = JSON.parse(t);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch (e) {
    return null;
  }
}

// ---------------------------------------------------------------------------
// El estado por telefono (CONTRATO §4). Se LEE aca y se ESCRIBE en un solo lugar,
// al final del turno (`Armar mensajes`).
// ---------------------------------------------------------------------------
function cnEstadoBase() {
  return {
    paso: 'inicio', servicio: null, hermanos: false, huecoElegido: null, moverId: null,
    ultimaOferta: [], ultimoMensajeMs: 0,
    // Agregados al contrato: lo que no cabe en el id de un boton y hay que
    // recordar entre dos mensajes.
    pacientes: [], moverInicio: null, moverTitulo: '', primerTexto: '', ultimoMensajeId: '', pidioSegundoNombre: false,
  };
}
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Un estado vencido (30 minutos) es `inicio`. Sin datos estaticos, tambien.
function cnLeerEstado(from, ahoraMs) {
  const base = cnEstadoBase();
  if (!cnClaveValida(from)) return base;
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  const mapa = sd && sd.agendaMinima && typeof sd.agendaMinima === 'object' ? sd.agendaMinima : null;
  if (!mapa || !Object.prototype.hasOwnProperty.call(mapa, from)) return base;
  const e = mapa[from];
  if (!e || typeof e !== 'object' || !(ahoraMs - Number(e.ultimoMensajeMs || 0) < CN_VENCE_MS)) return base;
  return Object.assign(base, e);
}

// La atencion del telefono: lo que devolvio la ingesta del entrante si lo trae, y si
// no, lo que dijo `configuracionFlujo`. Ante la duda, normal.
function cnAtencion(rIngesta, cfg) {
  const a = rIngesta && typeof rIngesta === 'object' && rIngesta.atencion && typeof rIngesta.atencion === 'object'
    ? rIngesta.atencion : null;
  const estados = ['normal', 'operador', 'bloqueado'];
  const estado = a && estados.indexOf(a.estado) >= 0 ? a.estado
    : (estados.indexOf(cfg.atencionEstado) >= 0 ? cfg.atencionEstado : 'normal');
  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : cfg.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || cfg.atencionMensajeFijo || '').trim(),
    // `a` puede ser null (la ingesta no trajo `atencion`): sin `a &&` delante, `a.respuestasEnVentana` lanzaba un TypeError
    // y el cliente se quedaba sin respuesta (hallazgo de la cartera, 01/10).
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : cfg.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || cfg.atencionVenceEn || ''),
  };
}

// RESUMEN DEL TURNO: el ultimo nodo. En produccion no hace nada visible. En la variante
// de prueba, «Entrada de prueba» responde con lo que devuelve este nodo: la lista de
// mensajes salientes del turno y un resumen, para que un corredor externo evalue cada
// turno sin depender de WhatsApp.
//
// Lee TODO por nombre de «Armar mensajes» y no de lo que devolvieron los nodos de envio
// ni de reporte (un nodo desactivado deja pasar su entrada). Corre una vez por cada rama
// que llega hasta aca y siempre da lo mismo.
const items = cnTodos('Armar mensajes');
const cfg = cnCfg();
const primero = items[0] || {};
const mensajes = items.filter((i) => i && i.sinMensajes !== true).map((i) => ({
  para: i.para, destino: i.destino, payload: i.payload, texto: i.texto, respaldo: i.respaldo, reportar: i.reportar === true,
}));
const r = primero.resumen || {
  plan: primero.plan || 'nada', estadoDespues: primero.estadoDespues || null, errores: primero.errores || [],
  huecosOfrecidos: primero.huecosOfrecidos || [], eventoCreadoId: primero.eventoCreadoId || '', eventoBorradoId: primero.eventoBorradoId || '',
};
let accion = r.plan;
if (r.eventoCreadoId) accion = r.eventoBorradoId ? 'cita_movida' : 'cita_creada';
else if (r.plan === 'cancelar' && r.eventoBorradoId) accion = 'cita_cancelada';
else if (r.plan === 'cruce') accion = 'cruce_deshecho';
return [{ json: {
  ok: true,
  modoPrueba: cfg.modoPrueba === true,
  mensajes: mensajes,
  resumen: {
    ruta: r.plan, accion: accion, huecosOfrecidos: r.huecosOfrecidos, eventoCreadoId: r.eventoCreadoId,
    eventoBorradoId: r.eventoBorradoId, estadoDespues: r.estadoDespues, errores: r.errores, mensajesSalientes: mensajes.length,
  },
} }];
